function rsiMarkup(){const closes=chartCandles.map(c=>c.close);if(closes.length<15)return '<div class="chart-empty">RSI needs at least 15 price candles.</div>';let gains=0,losses=0;for(let i=1;i<=14;i++){const d=closes[i]-closes[i-1];if(d>0)gains+=d;else losses-=d}let avgGain=gains/14,avgLoss=losses/14;for(let i=15;i<closes.length;i++){const d=closes[i]-closes[i-1];avgGain=(avgGain*13+Math.max(d,0))/14;avgLoss=(avgLoss*13+Math.max(-d,0))/14}const value=avgLoss===0?100:100-(100/(1+avgGain/avgLoss)),tone=value>=70?"overbought":value<=30?"oversold":"neutral",label=value>=70?"Potentially overbought":value<=30?"Potentially oversold":"Neutral momentum";return '<div class="rsi-readout"><b>'+value.toFixed(1)+'</b><span class="'+tone+'">'+label+'</span></div><div class="rsi-track"><i style="left:30%"></i><i style="left:70%"></i><span style="width:'+value.toFixed(1)+'%"></span></div><div class="rsi-scale"><span>0</span><span>30 · Oversold</span><span>70 · Overbought</span><span>100</span></div><small class="data-note">Relative Strength Index · 14 periods · educational signal, not a trade instruction</small>'}
